// TestClient provides a testsuite-compatible Client
type TestCartActorClient struct {
	env       *testsuite.TestWorkflowEnvironment
	workflows CartActorWorkflows
}

var _ CartActorClient = &TestCartActorClient{}

// NewTestCartActorClient initializes a new TestCartActorClient value
func NewTestCartActorClient(env *testsuite.TestWorkflowEnvironment, workflows CartActorWorkflows, activities CartActorActivities) *TestCartActorClient {
	if workflows != nil {
		RegisterCartActorWorkflows(env, workflows)
	}
	if activities != nil {
		RegisterCartActorActivities(env, activities)
	}
	return &TestCartActorClient{env, workflows}
}

// StartCart executes a(n) cart.v1.CartActor.StartCart workflow in the test environment
func (c *TestCartActorClient) StartCart(ctx context.Context, req *CartRequest, opts ...*StartCartOptions) (*CartResponse, error) {
	run, err := c.StartCartAsync(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return run.Get(ctx)
}

// StartCartAsync executes a(n) cart.v1.CartActor.StartCart workflow in the test environment
func (c *TestCartActorClient) StartCartAsync(ctx context.Context, req *CartRequest, options ...*StartCartOptions) (StartCartRun, error) {
	var o *StartCartOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewStartCartOptions()
	}
	opts, err := o.Build(req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing client.StartWorkflowOptions: %w", err)
	}
	return &testStartCartRun{client: c, env: c.env, opts: &opts, req: req, workflows: c.workflows}, nil
}

// GetStartCart is a noop
func (c *TestCartActorClient) GetStartCart(ctx context.Context, workflowID string, runID string) StartCartRun {
	return &testStartCartRun{env: c.env, workflows: c.workflows}
}

// CancelWorkflow requests cancellation of an existing workflow execution
func (c *TestCartActorClient) CancelWorkflow(ctx context.Context, workflowID string, runID string) error {
	c.env.CancelWorkflow()
	return nil
}

// TerminateWorkflow terminates an existing workflow execution
func (c *TestCartActorClient) TerminateWorkflow(ctx context.Context, workflowID string, runID string, reason string, details ...interface{}) error {
	return c.CancelWorkflow(ctx, workflowID, runID)
}

// CancelCartSignal executes a cart.v1.CartActor.CancelCartSignal signal
func (c *TestCartActorClient) CancelCartSignal(ctx context.Context, workflowID string, runID string, req *CancelCartSignalRequest) error {
	c.env.SignalWorkflow(CancelCartSignalSignalName, req)
	return nil
}

var _ StartCartRun = &testStartCartRun{}

// testStartCartRun provides convenience methods for interacting with a(n) cart.v1.CartActor.StartCart workflow in the test environment
type testStartCartRun struct {
	client    *TestCartActorClient
	env       *testsuite.TestWorkflowEnvironment
	opts      *client.StartWorkflowOptions
	req       *CartRequest
	workflows CartActorWorkflows
}

// Cancel requests cancellation of a workflow in execution, returning an error if applicable
func (r *testStartCartRun) Cancel(ctx context.Context) error {
	return r.client.CancelWorkflow(ctx, r.ID(), r.RunID())
}

// Get retrieves a test cart.v1.CartActor.StartCart workflow result
func (r *testStartCartRun) Get(context.Context) (*CartResponse, error) {
	r.env.ExecuteWorkflow(StartCartWorkflowName, r.req)
	if !r.env.IsWorkflowCompleted() {
		return nil, errors.New("workflow in progress")
	}
	if err := r.env.GetWorkflowError(); err != nil {
		return nil, err
	}
	var result CartResponse
	if err := r.env.GetWorkflowResult(&result); err != nil {
		return nil, err
	}
	return &result, nil
}

// ID returns a test cart.v1.CartActor.StartCart workflow run's workflow ID
func (r *testStartCartRun) ID() string {
	if r.opts != nil {
		return r.opts.ID
	}
	return ""
}

// Run noop implementation
func (r *testStartCartRun) Run() client.WorkflowRun {
	return nil
}

// RunID noop implementation
func (r *testStartCartRun) RunID() string {
	return ""
}

// Terminate terminates a workflow in execution, returning an error if applicable
func (r *testStartCartRun) Terminate(ctx context.Context, reason string, details ...interface{}) error {
	return r.client.TerminateWorkflow(ctx, r.ID(), r.RunID(), reason, details...)
}

// CartActorCliOptions describes runtime configuration for cart.v1.CartActor cli
type CartActorCliOptions struct {
	after            func(*v2.Context) error
	before           func(*v2.Context) error
	clientForCommand func(*v2.Context) (client.Client, error)
	worker           func(*v2.Context, client.Client) (worker.Worker, error)
}

// NewCartActorCliOptions initializes a new CartActorCliOptions value
func NewCartActorCliOptions() *CartActorCliOptions {
	return &CartActorCliOptions{}
}

// WithAfter injects a custom After hook to be run after any command invocation
