// NewCartActorCli initializes a cli for a(n) cart.v1.CartActor service
func NewCartActorCli(options ...*CartActorCliOptions) (*v2.App, error) {
	commands, err := newCartActorCommands(options...)
	if err != nil {
		return nil, fmt.Errorf("error initializing subcommands: %w", err)
	}
	return &v2.App{
		Name:                      "cart-actor",
		Commands:                  commands,
		DisableSliceFlagSeparator: true,
	}, nil
}

// NewCartActorCliCommand initializes a cli command for a cart.v1.CartActor service with subcommands for each query, signal, update, and workflow
func NewCartActorCliCommand(options ...*CartActorCliOptions) (*v2.Command, error) {
	subcommands, err := newCartActorCommands(options...)
	if err != nil {
		return nil, fmt.Errorf("error initializing subcommands: %w", err)
	}
	return &v2.Command{
		Name:        "cart-actor",
		Subcommands: subcommands,
	}, nil
}

// newCartActorCommands initializes (sub)commands for a cart.v1.CartActor cli or command
func newCartActorCommands(options ...*CartActorCliOptions) ([]*v2.Command, error) {
	opts := &CartActorCliOptions{}
	if len(options) > 0 {
		opts = options[0]
	}
	if opts.clientForCommand == nil {
		opts.clientForCommand = func(*v2.Context) (client.Client, error) {
			return client.Dial(client.Options{})
		}
	}
	commands := []*v2.Command{
		{
			Name:                   "cancel-cart-signal",
			Usage:                  "CancelCartSignal allows external callers to cancel the cart reservation.",
			Category:               "SIGNALS",
			UseShortOptionHandling: true,
			Before:                 opts.before,
			After:                  opts.after,
			Flags: []v2.Flag{
				&v2.StringFlag{
					Name:     "workflow-id",
					Usage:    "workflow id",
					Required: true,
					Aliases:  []string{"w"},
				},
				&v2.StringFlag{
					Name:    "run-id",
					Usage:   "run id",
					Aliases: []string{"r"},
				},
				&v2.StringFlag{
					Name:    "input-file",
					Usage:   "path to json-formatted input file",
					Aliases: []string{"f"},
				},
				&v2.StringFlag{
					Name:     "cart-id",
					Usage:    "set the value of the operation's \"CartId\" parameter",
					Category: "INPUT",
				},
				&v2.StringFlag{
					Name:     "reason",
					Usage:    "set the value of the operation's \"Reason\" parameter",
					Category: "INPUT",
				},
			},
			Action: func(cmd *v2.Context) error {
				c, err := opts.clientForCommand(cmd)
				if err != nil {
					return fmt.Errorf("error initializing client for command: %w", err)
				}
				defer c.Close()
				client := NewCartActorClient(c)
				req, err := UnmarshalCliFlagsToCancelCartSignalRequest(cmd)
				if err != nil {
					return fmt.Errorf("error unmarshalling request: %w", err)
				}
				if err := client.CancelCartSignal(cmd.Context, cmd.String("workflow-id"), cmd.String("run-id"), req); err != nil {
					return fmt.Errorf("error sending %q signal: %w", CancelCartSignalSignalName, err)
				}
				fmt.Println("success")
				return nil
			},
		},
		{
			Name:                   "start-cart",
			Usage:                  "Starts the shopping cart workflow.",
			Category:               "WORKFLOWS",
			UseShortOptionHandling: true,
			Before:                 opts.before,
			After:                  opts.after,
			Flags: []v2.Flag{
				&v2.BoolFlag{
					Name:    "detach",
					Usage:   "run workflow in the background and print workflow and execution id",
					Aliases: []string{"d"},
				},
				&v2.StringFlag{
					Name:     "task-queue",
					Usage:    "task queue name",
					Aliases:  []string{"t"},
					EnvVars:  []string{"TEMPORAL_TASK_QUEUE_NAME", "TEMPORAL_TASK_QUEUE", "TASK_QUEUE_NAME", "TASK_QUEUE"},
					Required: true,
				},
				&v2.StringFlag{
					Name:    "input-file",
					Usage:   "path to json-formatted input file",
					Aliases: []string{"f"},
				},
				&v2.StringFlag{
					Name:     "cart-id",
					Usage:    "set the value of the operation's \"CartId\" parameter",
					Category: "INPUT",
				},
				&v2.StringFlag{
					Name:     "customer-id",
					Usage:    "set the value of the operation's \"CustomerId\" parameter",
					Category: "INPUT",
				},
				&v2.StringFlag{
					Name:     "ticket-ids",
					Usage:    "Comma-separated ticket IDs.",
					Category: "INPUT",
				},
			},
			Action: func(cmd *v2.Context) error {
				tc, err := opts.clientForCommand(cmd)
				if err != nil {
					return fmt.Errorf("error initializing client for command: %w", err)
				}
				defer tc.Close()
				c := NewCartActorClient(tc)
				req, err := UnmarshalCliFlagsToCartRequest(cmd)
				if err != nil {
					return fmt.Errorf("error unmarshalling request: %w", err)
				}
				opts := client.StartWorkflowOptions{}
				if tq := cmd.String("task-queue"); tq != "" {
					opts.TaskQueue = tq
				}
				run, err := c.StartCartAsync(cmd.Context, req, NewStartCartOptions().WithStartWorkflowOptions(opts))
				if err != nil {
					return fmt.Errorf("error starting %s workflow: %w", StartCartWorkflowName, err)
				}
				if cmd.Bool("detach") {
					fmt.Println("success")
					fmt.Printf("workflow id: %s\n", run.ID())
					fmt.Printf("run id: %s\n", run.RunID())
					return nil
				}
				if resp, err := run.Get(cmd.Context); err != nil {
					return err
				} else {
					b, err := protojson.Marshal(resp)
					if err != nil {
						return fmt.Errorf("error serializing response json: %w", err)
					}
					var out bytes.Buffer
					if err := json.Indent(&out, b, "", "  "); err != nil {
						return fmt.Errorf("error formatting json: %w", err)
					}
					fmt.Println(out.String())
					return nil
				}
			},
		},
	}
	if opts.worker != nil {
		commands = append(commands, []*v2.Command{
			{
				Name:                   "worker",
				Usage:                  "runs a cart.v1.CartActor worker process",
				UseShortOptionHandling: true,
				Before:                 opts.before,
				After:                  opts.after,
				Action: func(cmd *v2.Context) error {
					c, err := opts.clientForCommand(cmd)
					if err != nil {
						return fmt.Errorf("error initializing client for command: %w", err)
					}
					defer c.Close()
					w, err := opts.worker(cmd, c)
					if opts.worker != nil {
						if err != nil {
							return fmt.Errorf("error initializing worker: %w", err)
						}
					}
					if err := w.Start(); err != nil {
						return fmt.Errorf("error starting worker: %w", err)
					}
					defer w.Stop()
					<-cmd.Context.Done()
					return nil
				},
			},
		}...)
	}
	sort.Slice(commands, func(i, j int) bool {
		return commands[i].Name < commands[j].Name
	})
	return commands, nil
}

// UnmarshalCliFlagsToCancelCartSignalRequest unmarshals a CancelCartSignalRequest from command line flags
func UnmarshalCliFlagsToCancelCartSignalRequest(cmd *v2.Context, options ...helpers.UnmarshalCliFlagsOptions) (*CancelCartSignalRequest, error) {
	var result CancelCartSignalRequest
	if cmd.IsSet("input-file") {
		inputFile, err := gohomedir.Expand(cmd.String("input-file"))
		if err != nil {
			inputFile = cmd.String("input-file")
		}
		b, err := os.ReadFile(inputFile)
		if err != nil {
			return nil, fmt.Errorf("error reading input-file: %w", err)
		}
		if err := protojson.Unmarshal(b, &result); err != nil {
			return nil, fmt.Errorf("error parsing input-file json: %w", err)
		}
	}
	opts := helpers.UnmarshalCliFlagsOptions{}
	if len(options) > 0 {
		opts = options[0]
	}
	if flag := opts.FlagName("cart-id"); cmd.IsSet(flag) {
		value := cmd.String(flag)
		result.CartId = value
	}
	if flag := opts.FlagName("reason"); cmd.IsSet(flag) {
		value := cmd.String(flag)
		result.Reason = value
	}
	return &result, nil
}

// UnmarshalCliFlagsToCartRequest unmarshals a CartRequest from command line flags
func UnmarshalCliFlagsToCartRequest(cmd *v2.Context, options ...helpers.UnmarshalCliFlagsOptions) (*CartRequest, error) {
	var result CartRequest
	if cmd.IsSet("input-file") {
		inputFile, err := gohomedir.Expand(cmd.String("input-file"))
		if err != nil {
			inputFile = cmd.String("input-file")
		}
		b, err := os.ReadFile(inputFile)
		if err != nil {
			return nil, fmt.Errorf("error reading input-file: %w", err)
		}
		if err := protojson.Unmarshal(b, &result); err != nil {
			return nil, fmt.Errorf("error parsing input-file json: %w", err)
		}
	}
	opts := helpers.UnmarshalCliFlagsOptions{}
	if len(options) > 0 {
		opts = options[0]
	}
	if flag := opts.FlagName("cart-id"); cmd.IsSet(flag) {
		value := cmd.String(flag)
		result.CartId = value
	}
	if flag := opts.FlagName("customer-id"); cmd.IsSet(flag) {
		value := cmd.String(flag)
		result.CustomerId = value
	}
	if flag := opts.FlagName("ticket-ids"); cmd.IsSet(flag) {
		value := cmd.String(flag)
		result.TicketIds = value
	}
	return &result, nil
}
